//! Golden vectors: `tests/vectors.json`.
//!
//! The file is GENERATED by this test from fixed seeds (Ed25519 is deterministic, so the output is
//! stable). On every run the test regenerates the vectors in memory and asserts they equal the
//! committed file, then checks every vector against BOTH ce-net-proto and ce-cap. Regenerate after
//! an intentional format change with `CE_NET_PROTO_REGEN=1 cargo test --test vectors`.

use ce_net_proto::delegate::{Grant, delegate};
use ce_net_proto::{
    Caveats, Identity, NodeId, Resource, SignedCapability, SignedRevocation, authorize, cap_bytes, decode_chain,
    encode_chain, revoke_bytes, verify_chain,
};
use serde_json::{Value, json};

const PATH: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/vectors.json");

fn key(n: u8) -> Identity {
    Identity::from_secret_bytes(&[n; 32])
}
fn h(b: &[u8]) -> String {
    hex::encode(b)
}
fn s(v: &[&str]) -> Vec<String> {
    v.iter().map(|x| x.to_string()).collect()
}

struct Case {
    name: &'static str,
    note: &'static str,
    chain: Vec<SignedCapability>,
    now: u64,
    revoked: Vec<(NodeId, u64)>,
    requester: u8,
    action: &'static str,
    tags: Vec<String>,
}

const ROOT: u8 = 1;
const NODE: u8 = 9;

fn cases() -> Vec<Case> {
    let (root, a, b) = (key(ROOT), key(2), key(3));
    let issued = vec![SignedCapability::issue(&root, a.node_id(), s(&["exec", "sync"]), Resource::Any, Caveats::default(), 1, None)];
    let root_c = SignedCapability::issue(
        &root,
        a.node_id(),
        s(&["exec", "sync", "app:spawn:*"]),
        Resource::Tag("gpu".into()),
        Caveats {
            not_before: 0,
            not_after: 2_000_000_000,
            max_cpu: Some(16),
            max_mem_mb: Some(65_536),
            max_credits: Some(1_000_000),
            allowed_ports: Some(vec![22, 443, 8080]),
            path_prefix: Some("/srv".into()),
        },
        10,
        None,
    );
    let delegated = delegate(
        &[root_c],
        &a,
        b.node_id(),
        &Grant { abilities: &["sync", "app:spawn:wasm"], resource: Some(Resource::AllOf(s(&["gpu", "linux"]))), ttl_secs: 3_600, nonce: 11 },
        1_700_000_000,
    )
    .unwrap();
    let expiring = vec![SignedCapability::issue(
        &root,
        a.node_id(),
        s(&["exec"]),
        Resource::Node(key(NODE).node_id()),
        Caveats { not_after: 1_700_000_000, ..Default::default() },
        20,
        None,
    )];
    let mut tampered = delegated.clone();
    tampered[1].cap.abilities.push("exec".into());
    let amplified = {
        let c0 = SignedCapability::issue(&root, a.node_id(), s(&["sync"]), Resource::Any, Caveats::default(), 30, None);
        let id0 = c0.id();
        vec![c0, SignedCapability::issue(&a, b.node_id(), s(&["sync", "exec"]), Resource::Any, Caveats::default(), 31, Some(id0))]
    };
    let gl = s(&["gpu", "linux"]);
    vec![
        Case { name: "issued", note: "single root link, no caveats", chain: issued.clone(), now: 1_700_000_000, revoked: vec![], requester: 2, action: "exec", tags: vec![] },
        Case { name: "delegated", note: "root -> a -> b via delegate(); every caveat field set; wildcard narrowed", chain: delegated.clone(), now: 1_700_000_100, revoked: vec![], requester: 3, action: "app:spawn:wasm", tags: gl.clone() },
        Case { name: "delegated-ability-not-granted", note: "leaf never received exec", chain: delegated.clone(), now: 1_700_000_100, revoked: vec![], requester: 3, action: "exec", tags: gl.clone() },
        Case { name: "delegated-expired", note: "leaf expiry clamped to now+ttl = 1700003600", chain: delegated.clone(), now: 1_700_003_601, revoked: vec![], requester: 3, action: "sync", tags: gl.clone() },
        Case { name: "expired", note: "root link not_after passed", chain: expiring.clone(), now: 1_700_000_001, revoked: vec![], requester: 2, action: "exec", tags: vec![] },
        Case { name: "not-yet-expired", note: "same token one second earlier (inclusive bound)", chain: expiring, now: 1_700_000_000, revoked: vec![], requester: 2, action: "exec", tags: vec![] },
        Case { name: "revoked-leaf", note: "(a, 11) revoked: leaf link dies", chain: delegated.clone(), now: 1_700_000_100, revoked: vec![(a.node_id(), 11)], requester: 3, action: "sync", tags: gl.clone() },
        Case { name: "revoked-root", note: "(root, 10) revoked: whole subtree dies", chain: delegated.clone(), now: 1_700_000_100, revoked: vec![(root.node_id(), 10)], requester: 3, action: "sync", tags: gl.clone() },
        Case { name: "revoked-other-issuer-same-nonce", note: "revocation key is (issuer, nonce): (b, 11) does not touch a's link", chain: delegated, now: 1_700_000_100, revoked: vec![(b.node_id(), 11)], requester: 3, action: "sync", tags: gl.clone() },
        Case { name: "tampered", note: "abilities edited after signing", chain: tampered, now: 1_700_000_100, revoked: vec![], requester: 3, action: "exec", tags: gl },
        Case { name: "amplified", note: "child link claims an ability its parent lacks (validly signed)", chain: amplified, now: 1_700_000_000, revoked: vec![], requester: 3, action: "sync", tags: vec![] },
        Case { name: "wrong-root", note: "issued chain checked against a different root key (key 2)", chain: issued, now: 1_700_000_000, revoked: vec![], requester: 2, action: "exec", tags: vec![] },
    ]
}

fn result_json(r: &Result<(), String>) -> Value {
    match r {
        Ok(()) => json!({ "ok": true }),
        Err(e) => json!({ "ok": false, "error": e }),
    }
}

fn generate() -> Value {
    let mut out = Vec::new();
    for c in cases() {
        let root_key = if c.name == "wrong-root" { key(2).node_id() } else { key(ROOT).node_id() };
        let is_rev = |i: &NodeId, n: u64| c.revoked.iter().any(|(ri, rn)| ri == i && *rn == n);
        let verify = verify_chain(&c.chain, &root_key, c.now, &is_rev).map(|_| ());
        let node = key(NODE).node_id();
        let auth = authorize(&node, &[root_key], &c.tags, c.now, &key(c.requester).node_id(), c.action, &c.chain, &is_rev);
        let links: Vec<Value> = c
            .chain
            .iter()
            .map(|l| {
                json!({
                    "issuer": h(&l.cap.issuer),
                    "audience": h(&l.cap.audience),
                    "nonce": l.cap.nonce,
                    "cap_bytes": h(&cap_bytes(&l.cap)),
                    "cap_id": h(&l.id()),
                    "sig": h(&l.sig),
                })
            })
            .collect();
        out.push(json!({
            "name": c.name,
            "note": c.note,
            "chain_hex": encode_chain(&c.chain),
            "links": links,
            "root": h(&root_key),
            "now": c.now,
            "revoked": c.revoked.iter().map(|(i, n)| json!({ "issuer": h(i), "nonce": n })).collect::<Vec<_>>(),
            "verify_chain": result_json(&verify),
            "authorize": {
                "self_id": h(&node),
                "accepted_roots": [h(&root_key)],
                "self_tags": c.tags,
                "requester": h(&key(c.requester).node_id()),
                "action": c.action,
                "expect": result_json(&auth),
            },
        }));
    }
    let r = SignedRevocation::issue(&key(2), 11, 1_700_003_600);
    json!({
        "format": "ce-net-proto capability vectors v1",
        "generated_by": "cargo test --test vectors (CE_NET_PROTO_REGEN=1 to rewrite)",
        "keys": (1u8..=9).filter(|n| [1, 2, 3, 9].contains(n)).map(|n| json!({
            "seed": h(&[n; 32]), "public": h(&key(n).node_id())
        })).collect::<Vec<_>>(),
        "chains": out,
        "revocations": [{
            "name": "revoke-a-11",
            "issuer": h(&r.revocation.issuer),
            "nonce": r.revocation.nonce,
            "not_after": r.revocation.not_after,
            "revoke_bytes": h(&revoke_bytes(&r.revocation)),
            "sig": h(&r.sig),
            "encoded": h(&r.encode()),
        }],
    })
}

#[test]
fn vectors_file_matches_generator() {
    let text = serde_json::to_string_pretty(&generate()).unwrap() + "\n";
    if std::env::var_os("CE_NET_PROTO_REGEN").is_some() || !std::path::Path::new(PATH).exists() {
        std::fs::write(PATH, &text).unwrap();
    }
    let on_disk = std::fs::read_to_string(PATH).unwrap();
    assert_eq!(on_disk, text, "tests/vectors.json is stale; rerun with CE_NET_PROTO_REGEN=1");
}

fn nid(v: &Value) -> NodeId {
    hex::decode(v.as_str().unwrap()).unwrap().try_into().unwrap()
}

/// Check every vector from the FILE (not the generator).
#[test]
fn vectors_verify() {
    let v: Value = serde_json::from_str(&std::fs::read_to_string(PATH).unwrap()).unwrap();
    let mut n = 0;
    for c in v["chains"].as_array().unwrap() {
        let token = c["chain_hex"].as_str().unwrap();
        let root = nid(&c["root"]);
        let now = c["now"].as_u64().unwrap();
        let revoked: Vec<(NodeId, u64)> =
            c["revoked"].as_array().unwrap().iter().map(|r| (nid(&r["issuer"]), r["nonce"].as_u64().unwrap())).collect();
        let is_rev = |i: &NodeId, n: u64| revoked.iter().any(|(ri, rn)| ri == i && *rn == n);
        let a = &c["authorize"];
        let tags: Vec<String> = a["self_tags"].as_array().unwrap().iter().map(|t| t.as_str().unwrap().to_string()).collect();
        let (self_id, req, action) = (nid(&a["self_id"]), nid(&a["requester"]), a["action"].as_str().unwrap());

        let nc = decode_chain(token).unwrap();
        // Per-link bytes match the vectors (compat/tests/vectors.rs also checks them against ce-cap).
        for (l, nl) in c["links"].as_array().unwrap().iter().zip(&nc) {
            assert_eq!(l["cap_bytes"].as_str().unwrap(), h(&cap_bytes(&nl.cap)));
            assert_eq!(l["cap_id"].as_str().unwrap(), h(&nl.id()));
        }
        let vr = verify_chain(&nc, &root, now, &is_rev).map(|_| ());
        assert_eq!(result_json(&vr), c["verify_chain"], "{}", c["name"]);
        let nr = authorize(&self_id, &[root], &tags, now, &req, action, &nc, &is_rev);
        assert_eq!(result_json(&nr), a["expect"], "{}", c["name"]);
        n += 1;
    }
    assert!(n >= 10);
    for r in v["revocations"].as_array().unwrap() {
        let b = hex::decode(r["encoded"].as_str().unwrap()).unwrap();
        assert!(SignedRevocation::decode(&b).unwrap().verify_sig().is_ok());
    }
}
